package net.civeira.phylax.feature.observe.observedsource.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.event.ObservedSourceEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedSourceEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedSourceEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedSource entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
